styles.cssStarter:
:root{--accent:#2fb36b;--dark:#1e1e1e;--ink:#151515;--body:#5d5d5d;--bg:#fff;--container:1120px;--gutter:32px;--section-y:96px;--radius:6px}
body{font-family:'Inter',sans-serif;font-size:13px;line-height:1.65;color:var(--body);background:var(--bg)}
.container{max-width:var(--container);padding:0 var(--gutter);margin:0 auto}
section{padding:var(--section-y) 0}
.dark{background:var(--dark);color:#bbb}.dark h2{color:#fff}
h1,h2,h3{font-family:'Poppins',sans-serif;font-weight:700;color:var(--ink);line-height:1.15}
h1{font-size:52px;color:#fff;text-transform:uppercase;text-align:center}h1 em,h2 em{font-style:normal;color:var(--accent)}
h2{font-size:32px}
.btn{display:inline-flex;align-items:center;height:34px;padding:0 18px;border-radius:99px;background:var(--accent);color:#fff;font-size:11px;font-weight:600}
.card{background:#2a2a2a;border-radius:var(--radius);padding:20px;color:#bbb}
@media(max-width:768px){:root{--section-y:64px;--gutter:20px}h1{font-size:32px}h2{font-size:24px}}

:root{--accent:#c8834a;--dark:#2a2719;--ink:#1d1b14;--body:#666;--bg:#fff;--container:1080px;--gutter:32px;--section-y:96px;--radius:16px}
body{font-family:'Open Sans',sans-serif;font-size:12px;line-height:1.6;color:var(--body);background:var(--bg)}
.container{max-width:var(--container);padding:0 var(--gutter);margin:0 auto}
section{padding:var(--section-y) 0}
.dark{background:var(--dark);color:#bdb8a8;border-radius:var(--radius)}.dark h1,.dark h2{color:#fff}
h1,h2,h3{font-weight:700;color:var(--ink);line-height:1.2}
h1{font-size:40px}
h2{font-size:28px}
.label{font-size:8px;text-transform:uppercase;letter-spacing:.1em;color:var(--accent)}
.btn{display:inline-flex;align-items:center;gap:6px;height:30px;padding:0 14px;background:var(--accent);color:#fff;font-size:10px}
.card{background:#fff;clip-path:polygon(0 0,70% 0,78% 6%,100% 6%,100% 100%,0 100%);padding:20px}
.marquee{font-size:60px;font-weight:700;color:transparent;-webkit-text-stroke:1px #bbb;white-space:nowrap}
@media(max-width:768px){:root{--section-y:64px;--gutter:20px}h1{font-size:30px}h2{font-size:22px}}

